bool IsCommandAllowedDuringLockdown(int command_id) {
  auto* session_manager = BlockedSessionManager::GetInstance();
  if (!session_manager->IsInLockdownMode()) {
    return true;
  }

  // Allow only essential commands
  return command_id == IDC_DEV_TOOLS || 
         command_id == IDC_ZOOM_PLUS ||
         command_id == IDC_ZOOM_MINUS;
}

